example.code:
#include <iostream>

int main()
{
    // 1. Standard for loop accumulating sum
    int sum = 0;
    for (int i = 1; i <= 5; ++i)
    {
        sum += i;
    }
    std::cout << "Sum 1 to 5: " << sum << "\n";

    // 2. Comma-separated multiple variables
    // i goes 0, 1, 2, 3, 4; j goes 4, 3, 2, 1, 0
    // terms: (0*4) + (1*3) + (2*2) + (3*1) + (4*0) = 0 + 3 + 4 + 3 + 0 = 10
    int pairProductSum = 0;
    for (int i = 0, j = 4; i < 5; i++, j--)
    {
        pairProductSum += (i * j);
    }
    std::cout << "Pair product sum: " << pairProductSum << "\n";

    return 0;
}

#include <iostream>

int main()
{
    int n = 0;

    // Pretest loop (while): condition fails immediately (0 iterations)
    int pretestCount = 0;
    while (n > 0)
    {
        pretestCount++;
    }

    // Posttest loop (do-while): body runs once regardless
    int posttestCount = 0;
    do
    {
        posttestCount++;
    } while (n > 0);

    std::cout << "Pretest iterations: " << pretestCount << "\n";
    std::cout << "Posttest iterations: " << posttestCount << "\n";

    return 0;
}
